package config

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// PortScanConf configures an optional external port scanner.
type PortScanConf struct {
	ScannerBinPath       string   `toml:"scannerBinPath,omitempty" json:"scannerBinPath,omitempty"`
	ScanTechniques       []string `toml:"scanTechniques,omitempty" json:"scanTechniques,omitempty"`
	HasPrivileged        bool     `toml:"hasPrivileged,omitempty" json:"hasPrivileged,omitempty"`
	SourcePort           string   `toml:"sourcePort,omitempty" json:"sourcePort,omitempty"`
	IsUseExternalScanner bool     `toml:"-" json:"-"`
}

// ScanTechnique is an nmap TCP scan technique.
type ScanTechnique int

const (
	// NotSupportTechnique indicates an unknown or unsupported scan technique.
	NotSupportTechnique ScanTechnique = iota
	// TCPSYN is a TCP SYN scan (-sS).
	TCPSYN
	// TCPConnect is a TCP connect scan (-sT).
	TCPConnect
	// TCPACK is a TCP ACK scan (-sA).
	TCPACK
	// TCPWindow is a TCP Window scan (-sW).
	TCPWindow
	// TCPMaimon is a TCP Maimon scan (-sM).
	TCPMaimon
	// TCPNull is a TCP Null scan (-sN).
	TCPNull
	// TCPFIN is a TCP FIN scan (-sF).
	TCPFIN
	// TCPXmas is a TCP Xmas scan (-sX).
	TCPXmas
)

// String returns the nmap scan technique code associated with the enum.
func (s ScanTechnique) String() string {
	switch s {
	case TCPSYN:
		return "sS"
	case TCPConnect:
		return "sT"
	case TCPACK:
		return "sA"
	case TCPWindow:
		return "sW"
	case TCPMaimon:
		return "sM"
	case TCPNull:
		return "sN"
	case TCPFIN:
		return "sF"
	case TCPXmas:
		return "sX"
	default:
		return "NotSupportTechnique"
	}
}

// GetScanTechniques converts configured nmap technique codes to enum values.
// Unknown values are kept as NotSupportTechnique so Validate can report them.
func (c *PortScanConf) GetScanTechniques() []ScanTechnique {
	if c == nil || len(c.ScanTechniques) == 0 {
		return []ScanTechnique{}
	}

	techniques := make([]ScanTechnique, 0, len(c.ScanTechniques))
	unsupportedAdded := false
	for _, configured := range c.ScanTechniques {
		technique := scanTechniqueFromString(configured)
		if technique == NotSupportTechnique {
			if !unsupportedAdded {
				techniques = append(techniques, NotSupportTechnique)
				unsupportedAdded = true
			}
			continue
		}
		techniques = append(techniques, technique)
	}
	return techniques
}

func scanTechniqueFromString(configured string) ScanTechnique {
	switch strings.ToLower(strings.TrimSpace(configured)) {
	case "ss":
		return TCPSYN
	case "st":
		return TCPConnect
	case "sa":
		return TCPACK
	case "sw":
		return TCPWindow
	case "sm":
		return TCPMaimon
	case "sn":
		return TCPNull
	case "sf":
		return TCPFIN
	case "sx":
		return TCPXmas
	default:
		return NotSupportTechnique
	}
}

// IsZero reports whether no port scan option was configured.
func (c PortScanConf) IsZero() bool {
	return c.ScannerBinPath == "" && len(c.ScanTechniques) == 0 && c.SourcePort == "" && !c.HasPrivileged
}

// Validate checks the external scanner settings.
func (c PortScanConf) Validate() (errs []error) {
	if c.IsZero() {
		return nil
	}

	var scannerExists bool
	if c.ScannerBinPath == "" {
		errs = append(errs, fmt.Errorf("scannerBinPath is required when portscan is configured"))
	} else if info, err := os.Stat(c.ScannerBinPath); err != nil {
		errs = append(errs, fmt.Errorf("scannerBinPath %q does not exist: %w", c.ScannerBinPath, err))
	} else if info.IsDir() {
		errs = append(errs, fmt.Errorf("scannerBinPath %q must be a file", c.ScannerBinPath))
	} else {
		scannerExists = true
	}

	if len(c.ScanTechniques) > 1 {
		errs = append(errs, fmt.Errorf("multiple scan techniques are not supported; configure at most one scan technique"))
	}
	hasTCPConnect := false
	hasNonConnectTechnique := false
	for _, configured := range c.ScanTechniques {
		technique := scanTechniqueFromString(configured)
		if technique == NotSupportTechnique {
			errs = append(errs, fmt.Errorf("unsupported scan technique %q", configured))
		} else if technique == TCPConnect {
			hasTCPConnect = true
		} else {
			hasNonConnectTechnique = true
		}
	}
	if !c.HasPrivileged && hasNonConnectTechnique {
		errs = append(errs, fmt.Errorf("only TCPConnect can be used when hasPrivileged is false"))
	}
	if c.SourcePort != "" && hasTCPConnect {
		errs = append(errs, fmt.Errorf("sourcePort cannot be used with TCPConnect scan technique"))
	}

	if c.SourcePort != "" {
		port, err := strconv.Atoi(c.SourcePort)
		if err != nil || port < 0 || port > 65535 {
			errs = append(errs, fmt.Errorf("sourcePort %q must be an integer between 0 and 65535", c.SourcePort))
		} else if port == 0 {
			errs = append(errs, fmt.Errorf("sourcePort 0 is not allowed; use a port between 1 and 65535"))
		}
	}

	if c.HasPrivileged && os.Geteuid() != 0 && scannerExists {
		if err := validateScannerCapabilities(c.ScannerBinPath); err != nil {
			errs = append(errs, err)
		}
	}
	return errs
}

var capabilityExpression = regexp.MustCompile(`^(cap_[a-z0-9_]+(?:,cap_[a-z0-9_]+)*)(?:=|\+)([eip-]+)$`)

func validateScannerCapabilities(scannerPath string) error {
	output, err := exec.Command("getcap", scannerPath).CombinedOutput()
	if err != nil {
		return fmt.Errorf("failed to inspect capabilities for scannerBinPath %q: %w", scannerPath, err)
	}
	line := strings.TrimSpace(string(output))
	if line == "" {
		return fmt.Errorf("scannerBinPath %q has no file capabilities; expected cap_net_raw with the effective flag", scannerPath)
	}
	if !strings.HasPrefix(line, scannerPath) {
		return fmt.Errorf("malformed capability data for scannerBinPath %q: %q", scannerPath, line)
	}
	capabilityData := strings.TrimSpace(strings.TrimPrefix(line, scannerPath))
	match := capabilityExpression.FindStringSubmatch(capabilityData)
	if len(match) != 3 {
		return fmt.Errorf("malformed capability data for scannerBinPath %q: %q", scannerPath, capabilityData)
	}
	hasNetRaw := false
	for _, capability := range strings.Split(match[1], ",") {
		if capability == "cap_net_raw" {
			hasNetRaw = true
			break
		}
	}
	if !hasNetRaw || !strings.Contains(match[2], "e") {
		return fmt.Errorf("scannerBinPath %q must have effective cap_net_raw capability; got %q", scannerPath, capabilityData)
	}
	return nil
}
		for _, e := range scanDest {
			if !m[e] {
				m[e] = true
				uniqScanDestIPPorts[i] = append(uniqScanDestIPPorts[i], e)
			}
		}
	}

	return uniqScanDestIPPorts
}

func (l *base) execPortsScan(scanDestIPPorts map[string][]string) ([]string, error) {
	if l.ServerInfo.PortScan != nil && l.ServerInfo.PortScan.IsUseExternalScanner {
		return l.execExternalPortScan(scanDestIPPorts)
	}
	return l.execNativePortScan(scanDestIPPorts)
}

func (l *base) execNativePortScan(scanDestIPPorts map[string][]string) ([]string, error) {
	listenIPPorts := []string{}

	for ip, ports := range scanDestIPPorts {
		if !isLocalExec(l.ServerInfo.Port, l.ServerInfo.Host) && net.ParseIP(ip).IsLoopback() {
			continue
		}
		for _, port := range ports {
			scanDest := ip + ":" + port
			conn, err := net.DialTimeout("tcp", scanDest, time.Duration(1)*time.Second)
			if err != nil {
				continue
			}
			conn.Close()
			listenIPPorts = append(listenIPPorts, scanDest)
		}
	}

	return listenIPPorts, nil
}

func (l *base) execExternalPortScan(scanDestIPPorts map[string][]string) ([]string, error) {
	portScan := l.ServerInfo.PortScan
	if portScan == nil || !portScan.IsUseExternalScanner {
		return nil, xerrors.Errorf("external port scanner is not configured")
	}

	scanOptions, err := setScanTechniques(portScan.GetScanTechniques())
	if err != nil {
		return nil, err
	}

	listenIPPorts := []string{}
	for ip, ports := range scanDestIPPorts {
		if !isLocalExec(l.ServerInfo.Port, l.ServerInfo.Host) && net.ParseIP(ip).IsLoopback() {
			continue
		}
		if len(ports) == 0 {
			continue
		}

		args := []string{"-n", "-Pn", "-oG", "-", "-p", strings.Join(ports, ",")}
		args = append(args, scanOptions...)
		if portScan.SourcePort != "" {
			args = append(args, "-g", portScan.SourcePort)
		}
		args = append(args, ip)

		cmd := osExec.Command(portScan.ScannerBinPath, args...)
		output, err := cmd.Output()
		if err != nil {
			if exitErr, ok := err.(*osExec.ExitError); ok && len(exitErr.Stderr) != 0 {
				err = xerrors.Errorf("%w: %s", err, strings.TrimSpace(string(exitErr.Stderr)))
			}
			return nil, xerrors.Errorf("failed to run external port scanner %s %s: %w",
				portScan.ScannerBinPath, formatNmapOptionsToString(args), err)
		}
		listenIPPorts = append(listenIPPorts, parseNmapGreppableOutput(output)...)
	}

	return listenIPPorts, nil
}

func setScanTechniques(techniques []config.ScanTechnique) ([]string, error) {
	options := make([]string, 0, len(techniques))
	for _, technique := range techniques {
		scanCode := technique.String()
		if scanCode == config.NotSupportTechnique.String() {
			return nil, xerrors.Errorf("unsupported scan technique")
		}
		options = append(options, "-"+scanCode)
	}
	return options, nil
}

func formatNmapOptionsToString(options []string) string {
	return strings.Join(options, " ")
}

func parseNmapGreppableOutput(output []byte) []string {
	openPorts := []string{}
	for _, line := range strings.Split(string(output), "\n") {
		parts := strings.SplitN(line, " Ports: ", 2)
		if len(parts) != 2 {
			continue
		}
		hostFields := strings.Fields(parts[0])
		if len(hostFields) < 2 {
			continue
		}
		host := strings.Trim(hostFields[1], "[]")
		for _, portInfo := range strings.Split(parts[1], ",") {
			fields := strings.Split(strings.TrimSpace(portInfo), "/")
			if len(fields) < 3 || !strings.EqualFold(fields[1], "open") || !strings.EqualFold(fields[2], "tcp") {
				continue
			}
			openPorts = append(openPorts, net.JoinHostPort(host, fields[0]))
		}
	}
	return openPorts
}

func (l *base) updatePortStatus(listenIPPorts []string) {
	for name, p := range l.osPackages.Packages {
		if p.AffectedProcs == nil {
			continue
		}
		for i, proc := range p.AffectedProcs {
			if proc.ListenPortStats == nil {
				continue
			}
			for j, port := range proc.ListenPortStats {
				l.osPackages.Packages[name].AffectedProcs[i].ListenPortStats[j].PortReachableTo = l.findPortScanSuccessOn(listenIPPorts, port)
			}
		}
	}
}

func (l *base) findPortScanSuccessOn(listenIPPorts []string, searchListenPort models.PortStat) []string {
	addrs := []string{}

	for _, ipPort := range listenIPPorts {
		ipPort, err := models.NewPortStat(ipPort)
		if err != nil {
			l.log.Warnf("Failed to find: %+v", err)
			continue
		}
		if searchListenPort.BindAddress == "*" {
			if searchListenPort.Port == ipPort.Port {
				addrs = append(addrs, ipPort.BindAddress)
			}
		} else if searchListenPort.BindAddress == ipPort.BindAddress && searchListenPort.Port == ipPort.Port {
			addrs = append(addrs, ipPort.BindAddress)
		}
	}

	return addrs
}

// findPortTestSuccessOn is retained for compatibility with existing callers.
func (l *base) findPortTestSuccessOn(listenIPPorts []string, searchListenPort models.PortStat) []string {
	return l.findPortScanSuccessOn(listenIPPorts, searchListenPort)
}

func (l *base) ps() (string, error) {
	cmd := `LANGUAGE=en_US.UTF-8 ps --no-headers --ppid 2 -p 2 --deselect -o pid,comm`
	r := l.exec(util.PrependProxyEnv(cmd), noSudo)
	if !r.isSuccess() {
		return "", xerrors.Errorf("Failed to SSH: %s", r)
	}
	return r.Stdout, nil
}

func (l *base) parsePs(stdout string) map[string]string {
	pidNames := map[string]string{}
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		ss := strings.Fields(line)
		if len(ss) < 2 {
			continue
		}
		pidNames[ss[0]] = ss[1]
	}
	return pidNames
}

func (l *base) lsProcExe(pid string) (string, error) {
	cmd := fmt.Sprintf("ls -l /proc/%s/exe", pid)
	r := l.exec(util.PrependProxyEnv(cmd), sudo)
	if !r.isSuccess() {
		return "", xerrors.Errorf("Failed to SSH: %s", r)
	}
	return r.Stdout, nil
}

