   925	func parseNmapGreppableOutput(output []byte) []string {
   926		openPorts := []string{}
   927		for _, line := range strings.Split(string(output), "\n") {
   928			portsIndex := strings.Index(line, "Ports:")
   929			if portsIndex == -1 {
   930				continue
   931			}
   932			hostFields := strings.Fields(line[:portsIndex])
   933			if len(hostFields) < 2 {
   934				continue
   935			}
   936			host := strings.Trim(hostFields[1], "[]")
   937			for _, portInfo := range strings.Split(line[portsIndex+len("Ports:"):], ",") {
   938				fields := strings.Split(strings.TrimSpace(portInfo), "/")
   939				if len(fields) < 3 || !strings.EqualFold(fields[1], "open") || !strings.EqualFold(fields[2], "tcp") {
   940					continue
   941				}
   942				openPorts = append(openPorts, net.JoinHostPort(host, fields[0]))
   943			}
   944		}
   945		return openPorts
   946	}
